            onClick={() => void addSelectedToExistingSupply()}
            data-testid="fbs-05-add-existing-submit"
          >
            Добавить заказы
          </Button>
        </DialogActions>
      </Dialog>

      <FbsSupplyCreateDialog
        token={token}
